import{_ as o,a0 as r,w as s,s as p,ao as l,I as i,x as n,a1 as e,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const U=JSON.parse('{"title":"Ubuntu 有望让你安装最新 Nvidia Linux 驱动更简单 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu 有望让你安装最新 Nvidia Linux 驱动更简单 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu 有望让你安装最新 Nvidia Linux 驱动更简单 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu 有望让你安装最新 Nvidia Linux 驱动更简单 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150813 Ubuntu Want To Make It Easier For You To Install The Latest Nvidia Linux Driver","title":"Ubuntu 有望让你安装最新 Nvidia Linux 驱动更简单","tag":"201508","desc":""},"relativePath":"201508/20150813 Ubuntu Want To Make It Easier For You To Install The Latest Nvidia Linux Driver.md","filePath":"[post].md"}'),d={name:"201508/20150813 Ubuntu Want To Make It Easier For You To Install The Latest Nvidia Linux Driver.md"};function b(m,t,x,T,g,v){const u=r("Link");return s(),p("div",null,[t[13]||(t[13]=l('<h1 id="ubuntu-有望让你安装最新-nvidia-linux-驱动更简单" tabindex="-1">Ubuntu 有望让你安装最新 Nvidia Linux 驱动更简单 <a class="header-anchor" href="#ubuntu-有望让你安装最新-nvidia-linux-驱动更简单" aria-label="Permalink to “Ubuntu 有望让你安装最新 Nvidia Linux 驱动更简单”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/03/ubuntugamer_logo_dark-500x250.jpg" alt="Ubuntu Gamers are on the rise -and so is demand for the latest drivers"></p><p><em>Ubuntu 上的游戏玩家在增长——因而需要最新版驱动</em></p><p><strong>在 Ubuntu 上安装上游的 NVIDIA 图形驱动即将变得更加容易。</strong></p><p>Ubuntu 开发者正在考虑构建一个全新的&#39;官方&#39; PPA，以便为桌面用户分发最新的闭源 NVIDIA 二进制驱动。</p><p>该项改变会让 Ubuntu 游戏玩家收益，并且<em>不会</em>给其它人造成 OS 稳定性方面的风险。</p><p><strong>仅</strong>当用户明确选择它时，新的上游驱动将通过这个新 PPA 安装并更新。其他人将继续得到并使用更近的包含在 Ubuntu 归档中的稳定版 NVIDIA Linux 驱动快照。</p><h3 id="为什么需要该项目" tabindex="-1">为什么需要该项目？ <a class="header-anchor" href="#为什么需要该项目" aria-label="Permalink to “为什么需要该项目？”">​</a></h3><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2013/04/drivers.jpg" alt="Ubuntu provides drivers – but they’re not the latest"></p><p><em>Ubuntu 提供了驱动——但是它们不是最新的</em></p><p>可以从归档中（使用命令行、synaptic，或者通过额外驱动工具）安装到 Ubuntu 上的闭源 NVIDIA 图形驱动在大多数情况下都能工作得很好，并且可以轻松地处理 Unity 桌面外壳的混染。</p><p>但对于游戏需求而言，那完全是另外一码事儿。</p><p>如果你想要将最高帧率和 HD 纹理从最新流行的 Steam 游戏中压榨出来，你需要最新的二进制驱动文件。</p><p>驱动越新，越可能支持最新的特性和技术，或者带有预先打包的游戏专门的优化和漏洞修复。</p><p>问题在于，在 Ubuntu 上安装最新 Nvidia Linux 驱动不是件容易的事儿，而且也不具安全保证。</p><p>要填补这个空白，许多由热心人维护的第三方 PPA 就出现了。由于许多这些 PPA 也发布了其它实验性的或者前沿软件，它们的使用<strong>并不是毫无风险的</strong>。添加一个前沿的 PPA 通常是搞崩整个系统的最快的方式！</p><p>一个解决方法是，让 Ubuntu 用户安装最新的专有图形驱动以满足对第三方 PPA 的需要，<strong>但是</strong>提供一个安全机制，如果有需要，你可以回滚到稳定版本。</p><h3 id="对全新驱动的需求难以忽视" tabindex="-1">‘对全新驱动的需求难以忽视’ <a class="header-anchor" href="#对全新驱动的需求难以忽视" aria-label="Permalink to “‘对全新驱动的需求难以忽视’”">​</a></h3><blockquote><p>&#39;一个让Ubuntu用户安全地获得最新硬件驱动的解决方案出现了。&#39;</p></blockquote><p>‘在快速发展的市场中，对全新驱动的需求正变得难以忽视，用户将想要最新的上游软件，’卡斯特罗在一封给 Ubuntu 桌面邮件列表的电子邮件中解释道。</p><p>‘[NVIDIA] 可以毫不费力为 [Windows 10] 用户带来了不起的体验。直到我们可以说服 NVIDIA 在 Ubuntu 中做了同样的工作，这样我们就可以搞定这一切了。’</p><p>卡斯特罗的“官方的” NVIDIA PPA 方案就是最实现这一目的的最容易的方式。</p><p>游戏玩家将可以在 Ubuntu 的默认专有软件驱动工具中选择接收来自该 PPA 的新驱动，再也不需要它们从网站或维基页面拷贝并粘贴终端命令了。</p><p>该 PPA 内的驱动将由一个选定的社区成员组成的团队打包并维护，并受惠于一个名为<strong>自动化测试</strong>的半官方方式。</p><p>就像卡斯特罗自己说的那样：&#39;人们想要最新的闪光的东西，而不管他们想要做什么。我们也许也要在其周围放置一个框架，因此人们可以获得他们所想要的，而不必破坏他们的计算机。&#39;</p><p><strong>你想要使用这个 PPA 吗？你怎样来评估 Ubuntu 上默认 Nvidia 驱动的性能呢？在评论中分享你的想法吧，伙计们！</strong></p><hr>',27)),i("p",null,[t[1]||(t[1]=n("via: ",-1)),e(u,{href:"http://www.omgubuntu.co.uk/2015/08/ubuntu-easy-install-latest-nvidia-linux-drivers"},{default:a(()=>[...t[0]||(t[0]=[n("http://www.omgubuntu.co.uk/2015/08/ubuntu-easy-install-latest-nvidia-linux-drivers",-1)])]),_:1})]),i("p",null,[t[5]||(t[5]=n("作者：",-1)),e(u,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:a(()=>[...t[2]||(t[2]=[n("Joey-Elijah Sneddon",-1)])]),_:1}),t[6]||(t[6]=n(" 译者：",-1)),e(u,{href:"https://github.com/GOLinux"},{default:a(()=>[...t[3]||(t[3]=[n("GOLinux",-1)])]),_:1}),t[7]||(t[7]=n(" 校对：",-1)),e(u,{href:"https://github.com/wxy"},{default:a(()=>[...t[4]||(t[4]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=n("本文由 ",-1)),e(u,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[8]||(t[8]=[n("LCTT",-1)])]),_:1}),t[11]||(t[11]=n(" 原创翻译，",-1)),e(u,{href:"https://linux.cn/"},{default:a(()=>[...t[9]||(t[9]=[n("Linux中国",-1)])]),_:1}),t[12]||(t[12]=n(" 荣誉推出",-1))])])}const N=o(d,[["render",b]]);export{U as __pageData,N as default};
